const source = $('Execute Workflow Trigger').item.json || {};
const args = source.args && typeof source.args === 'object' ? source.args : source;
const tool = String(source.tool || '').trim();
const baseUrl = String($env.HOME_ASSISTANT_URL || '').trim().replace(/\/+$/, '');
const token = String($env.HOME_ASSISTANT_TOKEN || '').trim();
const allowedLabel = String($env.MIA_HOME_ALLOWED_LABEL || 'mia_allowed').trim();
const allowedDomains = String($env.MIA_HOME_ALLOWED_DOMAINS || 'light,switch,fan,climate,media_player,scene,script')
  .split(',').map((item) => item.trim()).filter(Boolean);
const dashboardUrl = String($env.MIA_HOME_DASHBOARD_URL || '').trim();
const defaultArea = String($env.MIA_HOME_DEFAULT_AREA || '').trim();
const ttsEntityId = String($env.MIA_HOME_TTS_ENTITY_ID || '').trim();
let aliases = {};
try {
  aliases = JSON.parse(String($env.MIA_HOME_ENTITY_ALIASES_JSON || '{}').trim() || '{}');
} catch (error) {
  aliases = {};
}
const supportedTools = new Set([
  'smarthome.help',
  'smarthome.list_areas',
  'smarthome.list_devices',
  'smarthome.room_status',
  'smarthome.turn_on',
  'smarthome.turn_off',
  'smarthome.toggle',
  'smarthome.set_light',
  'smarthome.set_climate',
  'smarthome.set_fan',
  'smarthome.set_media',
  'smarthome.announce',
  'smarthome.run_scene',
]);
if (!supportedTools.has(tool)) {
  return [{ json: { ok: false, tool, text: `Unsupported smart home tool: ${tool}` } }];
}
if (tool !== 'smarthome.help' && (!baseUrl || !token)) {
  return [{ json: { ok: false, tool, text: 'Thiếu HOME_ASSISTANT_URL hoặc HOME_ASSISTANT_TOKEN.' } }];
}
const domainList = allowedDomains.map((item) => `'${String(item).replace(/'/g, "\\'")}'`).join(', ');
const inventoryTemplate = [
  `{% set label_name = ${JSON.stringify(allowedLabel)} %}`,
  `{% set allowed = label_entities(label_name) if label_name else states | map(attribute='entity_id') | list %}`,
  `{% set ns = namespace(rows=[]) %}`,
  `{% for entity_id in allowed %}`,
  `{% set domain = entity_id.split('.')[0] %}`,
  `{% if domain in [${domainList}] %}`,
  `{% set ns.rows = ns.rows + [{` +
    `'entity_id': entity_id, ` +
    `'domain': domain, ` +
    `'name': state_attr(entity_id, 'friendly_name') or entity_id, ` +
    `'state': states(entity_id), ` +
    `'area': area_name(entity_id) or '', ` +
    `'labels': labels(entity_id), ` +
    `'device_class': state_attr(entity_id, 'device_class'), ` +
    `'supported_color_modes': state_attr(entity_id, 'supported_color_modes'), ` +
    `'hvac_modes': state_attr(entity_id, 'hvac_modes'), ` +
    `'fan_modes': state_attr(entity_id, 'fan_modes'), ` +
    `'preset_modes': state_attr(entity_id, 'preset_modes'), ` +
    `'volume_level': state_attr(entity_id, 'volume_level'), ` +
    `'brightness': state_attr(entity_id, 'brightness')` +
  `}] %}`,
  `{% endif %}`,
  `{% endfor %}`,
  `{{ {'entities': ns.rows} | to_json }}`,
].join('\n');
return [{ json: { ...source, ok: true, tool, baseUrl, token, allowedLabel, allowedDomains, dashboardUrl, defaultArea, ttsEntityId, aliases, inventoryTemplate, args } }];

const source = $('Normalize Smart Home Request').item.json || {};
const tool = source.tool || '';
const args = source.args || {};
const aliases = source.aliases && typeof source.aliases === 'object' ? source.aliases : {};
function clean(value) { return String(value || '').trim(); }
function norm(value) {
  return clean(value)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/[^a-z0-9\s._-]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}
function title(value) { return clean(value) || 'thiết bị'; }
function parseInventory(payload) {
  if (payload && typeof payload === 'object' && Array.isArray(payload.entities)) return payload.entities;
  const text = typeof payload === 'string' ? payload : clean(payload?.data || payload?.body || payload?.text || payload?.output || '');
  if (!text) return [];
  try {
    const parsed = JSON.parse(text);
    return Array.isArray(parsed.entities) ? parsed.entities : [];
  } catch (error) {
    return [];
  }
}
const inventory = parseInventory($json);
if (!inventory.length) {
  return [{ json: { ok: false, tool, text: `Không thấy entity nào có label ${source.allowedLabel || 'mia_allowed'} trong Home Assistant.` } }];
}
const areaInput = clean(args.area || args.room || source.defaultArea);
const queryInput = clean(args.target || args.device || args.query || args.scene || args.entityId || args.entity_id || args.message);
const areaNorm = norm(areaInput);
const queryNorm = norm(queryInput);
const aliasExact = aliases[queryNorm] || aliases[queryInput] || '';
let candidates = inventory.slice();
if (areaNorm) {
  candidates = candidates.filter((item) => norm(item.area) === areaNorm || norm(item.area).includes(areaNorm));
}
function listAreas() {
  const unique = [...new Set(inventory.map((item) => clean(item.area)).filter(Boolean))].sort((a, b) => a.localeCompare(b, 'vi'));
  const lines = unique.length ? unique.map((name, index) => `${index + 1}. ${name}`) : ['Chưa có area nào trong phạm vi điều khiển.'];
  return { ok: true, tool, text: ['Các khu vực Mia đang nhìn thấy:', ...lines].join('\n'), result: { areas: unique }, links: source.dashboardUrl ? [source.dashboardUrl] : [] };
}
function listDevices() {
  let rows = candidates.slice();
  if (queryNorm) {
    rows = rows.filter((item) => [item.name, item.entity_id, item.domain].some((value) => norm(value).includes(queryNorm)));
  }
  const limit = Math.max(1, Math.min(Number(args.limit || 20) || 20, 50));
  rows = rows.slice(0, limit);
  const lines = rows.length
    ? rows.map((item, index) => `${index + 1}. ${title(item.name)} | ${item.domain} | ${item.state}${item.area ? ` | ${item.area}` : ''}`)
    : ['Không tìm thấy thiết bị phù hợp trong phạm vi cho phép.'];
  return { ok: true, tool, text: ['Thiết bị smart home:', ...lines].join('\n'), result: { devices: rows }, links: source.dashboardUrl ? [source.dashboardUrl] : [] };
}
function roomStatus() {
  const rows = candidates.slice().sort((a, b) => String(a.domain).localeCompare(String(b.domain)) || String(a.name).localeCompare(String(b.name), 'vi'));
  const roomName = areaInput || 'khu vực hiện tại';
  const lines = rows.length
    ? rows.map((item, index) => `${index + 1}. ${title(item.name)} | ${item.domain} | ${item.state}`)
    : ['Không có entity nào trong khu vực này.'];
  return { ok: true, tool, text: [`Trạng thái ${roomName}:`, ...lines].join('\n'), result: { devices: rows, area: roomName }, links: source.dashboardUrl ? [source.dashboardUrl] : [] };
}
function preferredDomains() {
  if (tool === 'smarthome.set_light') return ['light'];
  if (tool === 'smarthome.set_climate') return ['climate'];
  if (tool === 'smarthome.set_fan') return ['fan'];
  if (tool === 'smarthome.set_media' || tool === 'smarthome.announce') return ['media_player'];
  if (tool === 'smarthome.run_scene') return ['scene'];
  return [];
}
function score(item) {
  const itemName = norm(item.name);
  const entityId = norm(item.entity_id);
  const aliasId = clean(aliasExact);
  if (aliasId && clean(item.entity_id) === aliasId) return 200;
  if (queryNorm && entityId === queryNorm) return 190;
  if (queryNorm && itemName === queryNorm) return 180;
  if (queryNorm && entityId.endsWith(queryNorm)) return 140;
  if (queryNorm && itemName.includes(queryNorm)) return 120;
  if (queryNorm && entityId.includes(queryNorm)) return 110;
  return 0;
}
function resolveTarget() {
  const exactEntityId = clean(args.entityId || args.entity_id);
  let rows = candidates.slice();
  const domains = preferredDomains();
  if (domains.length) rows = rows.filter((item) => domains.includes(clean(item.domain)));
  if (exactEntityId) {
    const found = rows.find((item) => clean(item.entity_id) === exactEntityId) || inventory.find((item) => clean(item.entity_id) === exactEntityId);
    if (found) return { match: found, rows: [found] };
  }
  if (tool === 'smarthome.run_scene' && clean(args.scene)) {
    const sceneNorm = norm(args.scene);
    rows = rows.filter((item) => norm(item.name).includes(sceneNorm) || norm(item.entity_id).includes(sceneNorm));
  }
  const scored = rows.map((item) => ({ item, score: score(item) })).filter((row) => row.score > 0).sort((a, b) => b.score - a.score || title(a.item.name).localeCompare(title(b.item.name), 'vi'));
  if (!queryNorm && rows.length === 1) return { match: rows[0], rows };
  if (!scored.length) return { match: null, rows };
  if (scored.length > 1 && scored[0].score === scored[1].score) return { match: null, rows: scored.slice(0, 5).map((row) => row.item) };
  return { match: scored[0].item, rows: scored.map((row) => row.item) };
}
if (tool === 'smarthome.list_areas') return [{ json: listAreas() }];
if (tool === 'smarthome.list_devices') return [{ json: listDevices() }];
if (tool === 'smarthome.room_status') return [{ json: roomStatus() }];
const resolved = resolveTarget();
if (!resolved.match) {
  const hintLines = resolved.rows && resolved.rows.length
    ? resolved.rows.slice(0, 5).map((item, index) => `${index + 1}. ${title(item.name)} | ${item.domain}${item.area ? ` | ${item.area}` : ''}`)
    : ['Không tìm thấy target phù hợp trong phạm vi label an toàn.'];
  return [{ json: { ok: false, tool, text: ['Mia chưa xác định chắc thiết bị cần điều khiển.', ...hintLines].join('\n') } }];
}
const target = resolved.match;
let serviceDomain = 'homeassistant';
let serviceName = 'turn_on';
let serviceData = { entity_id: target.entity_id };
let resultText = `Đã xử lý ${title(target.name)}.`;
if (tool === 'smarthome.turn_off') { serviceName = 'turn_off'; resultText = `Đã tắt ${title(target.name)}.`; }
else if (tool === 'smarthome.toggle') { serviceName = 'toggle'; resultText = `Đã đảo trạng thái ${title(target.name)}.`; }
else if (tool === 'smarthome.set_light') {
  serviceDomain = 'light'; serviceName = 'turn_on'; resultText = `Đã cập nhật đèn ${title(target.name)}.`;
  if (Number(args.brightnessPct || 0) > 0) serviceData.brightness_pct = Number(args.brightnessPct);
  if (Number(args.colorTempKelvin || 0) > 0) serviceData.color_temp_kelvin = Number(args.colorTempKelvin);
  if (clean(args.rgbColor)) {
    const rgb = clean(args.rgbColor).split(',').map((item) => Number(item.trim())).filter((value) => Number.isFinite(value));
    if (rgb.length === 3) serviceData.rgb_color = rgb.slice(0, 3);
  }
  if (Number(args.transitionSeconds || 0) > 0) serviceData.transition = Number(args.transitionSeconds);
}
else if (tool === 'smarthome.set_climate') {
  serviceDomain = 'climate';
  if (norm(args.hvacMode) === 'off') { serviceName = 'turn_off'; resultText = `Đã tắt điều hòa ${title(target.name)}.`; }
  else if (Number(args.temperature || 0) > 0 || clean(args.hvacMode)) {
    serviceName = 'set_temperature';
    if (Number(args.temperature || 0) > 0) serviceData.temperature = Number(args.temperature);
    if (clean(args.hvacMode)) serviceData.hvac_mode = clean(args.hvacMode);
    resultText = `Đã cập nhật điều hòa ${title(target.name)}.`;
  } else if (clean(args.fanMode)) {
    serviceName = 'set_fan_mode'; serviceData.fan_mode = clean(args.fanMode); resultText = `Đã đổi fan mode cho ${title(target.name)}.`;
  } else if (clean(args.swingMode)) {
    serviceName = 'set_swing_mode'; serviceData.swing_mode = clean(args.swingMode); resultText = `Đã đổi swing mode cho ${title(target.name)}.`;
  } else {
    serviceName = 'turn_on'; resultText = `Đã bật ${title(target.name)}.`;
  }
}
else if (tool === 'smarthome.set_fan') {
  serviceDomain = 'fan';
  if (Number(args.percentage || 0) > 0) { serviceName = 'set_percentage'; serviceData.percentage = Number(args.percentage); resultText = `Đã chỉnh tốc độ ${title(target.name)}.`; }
  else if (clean(args.presetMode)) { serviceName = 'set_preset_mode'; serviceData.preset_mode = clean(args.presetMode); resultText = `Đã đổi preset mode cho ${title(target.name)}.`; }
  else if (clean(args.direction)) { serviceName = 'set_direction'; serviceData.direction = clean(args.direction); resultText = `Đã đổi hướng quạt ${title(target.name)}.`; }
  else { serviceName = 'turn_on'; resultText = `Đã bật ${title(target.name)}.`; }
}
else if (tool === 'smarthome.set_media') {
  serviceDomain = 'media_player';
  const action = norm(args.action || '');
  if (Number(args.volumeLevel || 0) > 0) { serviceName = 'volume_set'; serviceData.volume_level = Number(args.volumeLevel); resultText = `Đã chỉnh âm lượng ${title(target.name)}.`; }
  else if (clean(args.mediaContentId)) { serviceName = 'play_media'; serviceData.media_content_id = clean(args.mediaContentId); serviceData.media_content_type = clean(args.mediaContentType || 'music'); resultText = `Đã yêu cầu ${title(target.name)} phát nội dung.`; }
  else if (action === 'pause') { serviceName = 'media_pause'; resultText = `Đã tạm dừng ${title(target.name)}.`; }
  else if (action === 'stop') { serviceName = 'media_stop'; resultText = `Đã dừng ${title(target.name)}.`; }
  else if (action === 'play') { serviceName = 'media_play'; resultText = `Đã tiếp tục phát trên ${title(target.name)}.`; }
  else if (action === 'turn_off') { serviceName = 'turn_off'; resultText = `Đã tắt ${title(target.name)}.`; }
  else { serviceName = 'media_play_pause'; resultText = `Đã đổi trạng thái phát cho ${title(target.name)}.`; }
}
else if (tool === 'smarthome.announce') {
  if (!clean(source.ttsEntityId)) {
    return [{ json: { ok: false, tool, text: 'Thiếu MIA_HOME_TTS_ENTITY_ID nên chưa thể phát TTS qua loa.' } }];
  }
  serviceDomain = 'tts'; serviceName = 'speak';
  serviceData = { entity_id: clean(source.ttsEntityId), media_player_entity_id: target.entity_id, message: clean(args.message || args.text || args.instruction) };
  if (!serviceData.message) {
    return [{ json: { ok: false, tool, text: 'Thiếu nội dung thông báo để phát qua loa.' } }];
  }
  resultText = `Đã phát thông báo trên ${title(target.name)}.`;
}
else if (tool === 'smarthome.run_scene') {
  serviceDomain = 'scene'; serviceName = 'turn_on'; resultText = `Đã chạy scene ${title(target.name)}.`;
}
return [{ json: { ok: true, tool, needsService: true, serviceUrl: `${source.baseUrl}/api/services/${serviceDomain}/${serviceName}`, serviceData, target, text: resultText, result: { resolvedTarget: target, serviceDomain, serviceName }, links: source.dashboardUrl ? [source.dashboardUrl] : [], meta: { requestId: source.requestId || '' } } }];

const planned = $('Plan Smart Home Action').item.json || {};
const payload = $json || {};
const failure = String(payload.message || payload.error || payload.error_message || '').trim();
if (failure) {
  return [{ json: { ok: false, tool: planned.tool || '', text: failure } }];
}
return [{ json: { ok: true, tool: planned.tool || '', text: planned.text || 'Đã xử lý smart home.', result: payload, links: planned.links || [], meta: planned.meta || {} } }];
